import React, { useState, useContext } from "react";
import API from "../api";
import { AuthContext } from "../App";
import { useNavigate, Link } from "react-router-dom";

export default function Login() {
  const { setAuth } = useContext(AuthContext);
  const nav = useNavigate();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState(null);

  const submit = async (e) => {
    e.preventDefault();
    setErr(null);
    setLoading(true);
    try {
      const res = await API.post("/auth/login", { email, password });
      if (res.data.success) {
        localStorage.setItem("token", res.data.token);
        localStorage.setItem("role", res.data.role);
        localStorage.setItem("userId", res.data.userId);
        setAuth({ token: res.data.token, role: res.data.role, userId: res.data.userId });
        nav("/dashboard");
      }
    } catch (e) {
      setErr(e.response?.data?.message || "Login failed. Check your credentials.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-wrapper">
      <div className="login-card card">
        <div className="login-hero">
          <div style={{display:"flex", alignItems:"center", gap:12}}>
            <div style={{
              width:56, height:56, borderRadius:12, background:"rgba(255,255,255,0.12)",
              display:"flex", alignItems:"center", justifyContent:"center", fontWeight:800, fontSize:20
            }}>
              ET
            </div>
            <div>
              <h1>EdTech Task Manager</h1>
              <p>Role-based task tracking for students and teachers. Fast, secure and simple.</p>
            </div>
          </div>
        </div>

        <div className="login-form">
          <div className="brand">
            <div className="logo">ED</div>
            <div>
              <h3>Welcome back</h3>
              <div className="small">Sign in to continue to your dashboard</div>
            </div>
          </div>

          {err && <div className="form-error">{err}</div>}

          <form className="form" onSubmit={submit}>
            <input
              className="input"
              placeholder="Email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              type="email"
              required
            />
            <input
              className="input"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              type="password"
              required
            />

            <div style={{display:"flex", justifyContent:"space-between", alignItems:"center"}}>
              <div className="small">Don't have an account? <Link to="/signup">Sign up</Link></div>
              <button className="btn btn-primary" type="submit" disabled={loading}>
                {loading ? "Signing in..." : "Sign in"}
              </button>
            </div>
          </form>

          <div style={{marginTop:16}} className="small">
            Use the seeded accounts: <br/>
            <strong>teacher@example.com / Teacher@123</strong> or <strong>student@example.com / Student@123</strong>
          </div>
        </div>
      </div>
    </div>
  );
}
